"""The override pack of X-Plane airports without their flatten (#123)."""
import json
import os

import pytest

import O4_File_Names as FNAMES
import O4_UI_Utils as UI
import O4_XP_Airports as XPAPT

# BGGH lies in +64-052; CROS reaches from +10+010 into +10+011.
APT_DAT = (
    "A\r\n1200 Generated by WorldEditor\r\n\r\n"
    "1    282 0 0 BGGH Nuuk\r\n"
    "1302 city Nuuk\r\n"
    "1302 flatten 1\r\n"
    "100 44.81 1 627 0.00 0 3 0  04 64.18 -51.686 0 0 3 1 0 3 22 64.20 -51.672 0 0 3 1 0 3\r\n"
    "130 Airport Boundary\r\n"
    "111 64.18 -51.69\r\n111 64.18 -51.67\r\n111 64.20 -51.67\r\n113 64.20 -51.69\r\n"
    "\r\n"
    "16   10 0 0 XSEA Seaplane base after BGGH\r\n"
    "1302 flatten 1\r\n"
    "\r\n"
    "1    30 0 0 CROS Crosses a tile edge Äö 東\r\n"
    "1302 flatten 1\r\n"
    "130 Airport Boundary\r\n"
    "111 10.5 10.9\r\n111 10.5 11.1\r\n111 10.6 11.1\r\n113 10.6 10.9\r\n"
    "\r\n"
    "17   10 0 0 XHEL Heliport\r\n"
    "99\r\n"
)


def test_extract_blocks_drops_only_the_flatten_line():
    lines = APT_DAT.encode("utf-8").splitlines(keepends=True)
    blocks = XPAPT.extract_blocks(lines, ["BGGH", "CROS", "NONE"])
    assert set(blocks) == {"BGGH", "CROS"}
    assert blocks["BGGH"][0] == "1    282 0 0 BGGH Nuuk"
    assert "1302 city Nuuk" in blocks["BGGH"]
    assert not any("flatten" in line for b in blocks.values() for line in b)
    # Ends before the next airport header (here a seaplane base, row 16),
    # with the trailing blank line dropped.
    assert blocks["BGGH"][-1] == "113 64.20 -51.69"
    assert blocks["CROS"][-1] == "113 10.6 10.9"
    assert blocks["CROS"][0].endswith("Äö 東")


def test_pack_file_is_utf8_with_crlf(tmp_path):
    blocks = XPAPT.extract_blocks(APT_DAT.splitlines(), ["CROS"])
    path = tmp_path / "apt.dat"
    XPAPT._write_apt_dat(str(path), XPAPT.pack_text(blocks))
    data = path.read_bytes()
    assert data.startswith(b"I\r\n1200 ")
    assert data.endswith(b"\r\n99\r\n")
    assert b"\r\r" not in data and b"\n" not in data.replace(b"\r\n", b"")
    assert "Äö 東".encode("utf-8") in data
    assert not [f for f in os.listdir(tmp_path) if f.startswith(".tmp")]


def test_marker_written_and_removed(tmp_path):
    XPAPT.write_marker(str(tmp_path), ["CROS", "BGGH", "BGGH"])
    assert json.loads((tmp_path / XPAPT.MARKER).read_text()) == ["BGGH", "CROS"]
    assert XPAPT.read_marker(str(tmp_path)) == {"BGGH", "CROS"}
    XPAPT.write_marker(str(tmp_path), [])
    assert not (tmp_path / XPAPT.MARKER).exists()
    XPAPT.write_marker(str(tmp_path), [])  # nothing to remove: no error
    assert XPAPT.read_marker(str(tmp_path)) == set()


def make_tile(tile_dir, lat, lon, icaos, dsf_after_marker=True):
    build_dir = FNAMES.build_dir(lat, lon, str(tile_dir) + os.sep)
    os.makedirs(build_dir, exist_ok=True)
    XPAPT.write_marker(build_dir, icaos)
    dsf = FNAMES.dsf_file(build_dir, lat, lon)
    os.makedirs(os.path.dirname(dsf), exist_ok=True)
    with open(dsf, "wb") as f:
        f.write(b"XPLNEDSF")
    marker = XPAPT.marker_path(build_dir)
    if icaos:
        t = os.path.getmtime(marker)
        os.utime(dsf, (t + 10, t + 10) if dsf_after_marker else (t - 10, t - 10))
    return build_dir


def test_built_flat_tiles_needs_a_dsf_not_older_than_the_marker(tmp_path):
    make_tile(tmp_path, 64, -52, ["BGGH"])
    make_tile(tmp_path, 10, 10, ["CROS"], dsf_after_marker=False)
    make_tile(tmp_path, 10, 11, [])
    (tmp_path / "zOrtho4XP_junk").mkdir()
    assert XPAPT.built_flat_tiles(str(tmp_path)) == {(64, -52): {"BGGH"}}


def test_override_needs_every_tile_the_boundary_reaches():
    airports = XPAPT.parse_apt_dat(APT_DAT.splitlines())
    assert XPAPT.airport_tiles(
        [a for a in airports if a["icao"] == "CROS"][0]) == {(10, 10), (10, 11)}
    flat = {(64, -52): {"BGGH"}, (10, 10): {"CROS"}}
    assert XPAPT.override_airports(airports, flat) == ["BGGH"]
    flat[(10, 11)] = {"CROS"}
    assert XPAPT.override_airports(airports, flat) == ["BGGH", "CROS"]
    # A tile built flat for another airport does not count.
    flat[(64, -52)] = {"BGGO"}
    assert XPAPT.override_airports(airports, flat) == ["CROS"]


@pytest.fixture
def xp(tmp_path, monkeypatch):
    """A fake X-Plane Global Scenery, tile folder and pack folder."""
    monkeypatch.setattr(FNAMES, "Tmp_dir", str(tmp_path / "tmp"))
    monkeypatch.setattr(UI, "log", False)
    gs = tmp_path / "X-Plane" / "Global Scenery"
    src = gs / "X-Plane 12 Global Scenery"
    src.mkdir(parents=True)
    apt = gs / "Global Airports" / "Earth nav data" / "apt.dat"
    apt.parent.mkdir(parents=True)
    apt.write_bytes(APT_DAT.encode("utf-8"))
    tiles = tmp_path / "Tiles"
    tiles.mkdir()
    pack = tmp_path / "pack"
    return (str(src), str(tiles), str(pack))


def pack_airports(pack):
    with open(os.path.join(pack, XPAPT.PACK_APT_DAT), encoding="utf-8") as f:
        return [line.split()[4] for line in f
                if line.split()[:1] in (["1"], ["16"], ["17"])]


def test_update_writes_pack_and_skips_when_nothing_changed(xp, monkeypatch):
    (src, tiles, pack) = xp
    make_tile(tiles, 64, -52, ["BGGH"])
    assert XPAPT.update_override_pack(("", src), tiles, pack) == 1
    assert pack_airports(pack) == ["BGGH"]
    calls = []
    real = XPAPT.extract_blocks
    monkeypatch.setattr(XPAPT, "extract_blocks",
                        lambda f, i: calls.append(1) or real(f, i))
    assert XPAPT.update_override_pack(("", src), tiles, pack) == 1
    assert calls == []  # same airports, same apt.dat: not rewritten
    make_tile(tiles, 10, 10, ["CROS"])
    make_tile(tiles, 10, 11, ["CROS"])
    assert XPAPT.update_override_pack(("", src), tiles, pack) == 2
    assert pack_airports(pack) == ["BGGH", "CROS"] and calls == [1]
    # A tile rebuilt without the airport flat: it leaves the pack.
    XPAPT.write_marker(FNAMES.build_dir(64, -52, tiles + os.sep), [])
    assert XPAPT.update_override_pack(("", src), tiles, pack) == 1
    assert pack_airports(pack) == ["CROS"]


def test_update_does_nothing_without_setting_or_apt_dat(xp, monkeypatch):
    (src, tiles, pack) = xp
    make_tile(tiles, 64, -52, ["BGGH"])
    assert XPAPT.update_override_pack(("",), tiles, pack) is None
    monkeypatch.setattr(XPAPT, "xp_flatten_airports", False)
    assert XPAPT.update_override_pack((src,), tiles, pack) is None
    assert not os.path.exists(pack)


def test_update_empty_pack_when_no_tile_is_built_flat(xp):
    (src, tiles, pack) = xp
    assert XPAPT.update_override_pack((src,), tiles, pack) == 0
    with open(os.path.join(pack, XPAPT.PACK_APT_DAT), "rb") as f:
        assert f.read().endswith(b"\r\n\r\n99\r\n")
